script:
(function(){
  try {
    if (!document.querySelector('link[data-amn-poppins]')) {
      var pf=document.createElement('link'); pf.rel='stylesheet'; pf.setAttribute('data-amn-poppins','1');
      pf.href='https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap';
      document.head.appendChild(pf);
    }
  } catch(e){}
})();

(function () {
  var $ = function (s) { return root_element.querySelector(s); };

  try {
    if (!document.querySelector('link[data-amd-poppins]')) {
      var pf = document.createElement('link');
      pf.rel = 'stylesheet'; pf.setAttribute('data-amd-poppins', '1');
      pf.href = 'https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap';
      document.head.appendChild(pf);
    }
  } catch (e) {}

  function esc(s) { var d = document.createElement('div'); d.textContent = s == null ? '' : s; return d.innerHTML; }
  function q(s) { return encodeURIComponent(s); }

  function count(doctype, filters) {
    return frappe.call({ method: 'frappe.client.get_count', args: { doctype: doctype, filters: filters } })
      .then(function (r) { return (r && r.message) || 0; });
  }
  function list(doctype, filters, fields, limit, order) {
    return frappe.call({
      method: 'frappe.client.get_list',
      args: { doctype: doctype, filters: filters, fields: fields,
              limit_page_length: limit || 0, order_by: order || 'modified desc' }
    }).then(function (r) { return (r && r.message) || []; });
  }

  function kpi(host, value, label, href, colour) {
    var a = document.createElement('a');
    a.className = 'amd-kpi';
    a.href = href;
    a.innerHTML = '<div class="amd-kpi-n" style="color:' + colour + '">' + value + '</div>' +
                  '<div class="amd-kpi-l">' + esc(label) + '</div>';
    host.appendChild(a);
  }

  function bars(host, rows, colour) {
    host.innerHTML = '';
    if (!rows.length) { host.innerHTML = '<div class="amd-empty">Nothing to show.</div>'; return; }
    var max = Math.max.apply(null, rows.map(function (r) { return r.value; })) || 1;
    rows.forEach(function (r) {
      var el = document.createElement('div');
      el.className = 'amd-bar-row';
      var label = r.href
        ? '<a href="' + r.href + '">' + esc(r.label) + '</a>'
        : esc(r.label);
      el.innerHTML = '<div class="amd-bar-lb">' + label + '</div>' +
                     '<div class="amd-track"><div class="amd-fill" style="width:' +
                     Math.max(3, Math.round((r.value / max) * 100)) + '%;background:' + colour + '"></div></div>' +
                     '<div class="amd-bar-vl">' + r.value + '</div>';
      host.appendChild(el);
    });
  }

  var AGO = 90;

  function load() {
    $('[data-amd-sub]').textContent = 'Loading…';
    var since = frappe.datetime.add_days(frappe.datetime.get_today(), -AGO);
    var monthStart = frappe.datetime.get_today().slice(0, 8) + '01';

    Promise.all([
      count('Asset Repair', { repair_status: 'Pending', docstatus: ['<', 2] }),
      count('Asset Repair', { workflow_state: ['like', 'Pending%'] }),
      count('Asset Check Sheet', { check_date: ['>=', monthStart], docstatus: ['<', 2] }),
      count('Asset Check Sheet', { overall_status: ['!=', 'Passed'], docstatus: ['<', 2] }),
      count('Equipment Request', { docstatus: ['<', 2] }),
      count('Asset', { docstatus: 1 }),
      list('Asset Repair', { workflow_state: ['is', 'set'], docstatus: ['<', 2] }, ['workflow_state'], 0),
      list('Asset Repair', { failure_date: ['>=', since] }, ['asset', 'asset_name'], 0),
      list('Asset Check Sheet', { overall_status: ['!=', 'Passed'], docstatus: ['<', 2] },
           ['name', 'asset', 'check_date', 'overall_status'], 8, 'check_date desc')
    ]).then(function (out) {
      var kp = $('[data-amd-kpis]');
      kp.innerHTML = '';
      kpi(kp, out[0], 'Repairs still open', '/app/asset-repair?repair_status=Pending', '#dc2626');
      kpi(kp, out[1], 'Waiting on an approval', '/app/asset-repair', '#ea580c');
      kpi(kp, out[2], 'Checks done this month', '/app/asset-check-sheet', '#2563eb');
      kpi(kp, out[3], 'Checks that found a fault', '/app/asset-check-sheet?overall_status=%5B%22!%3D%22%2C%22Passed%22%5D', '#b45309');
      kpi(kp, out[4], 'Equipment requests', '/app/equipment-request', '#7c3aed');
      kpi(kp, out[5], 'Assets on the register', '/app/asset', '#475569');

      var byStage = {};
      out[6].forEach(function (r) { byStage[r.workflow_state] = (byStage[r.workflow_state] || 0) + 1; });
      bars($('[data-amd-stages]'), Object.keys(byStage).map(function (k) {
        return { label: k, value: byStage[k], href: '/app/asset-repair?workflow_state=' + q(k) };
      }).sort(function (a, b) { return b.value - a.value; }), '#ea580c');

      var byAsset = {};
      out[7].forEach(function (r) {
        var k = r.asset_name || r.asset;
        if (!k) return;
        byAsset[k] = byAsset[k] || { n: 0, id: r.asset };
        byAsset[k].n += 1;
      });
      bars($('[data-amd-assets]'), Object.keys(byAsset).map(function (k) {
        return { label: k, value: byAsset[k].n, href: '/app/asset-repair?asset=' + q(byAsset[k].id) };
      }).sort(function (a, b) { return b.value - a.value; }).slice(0, 8), '#dc2626');

      var tb = $('[data-amd-faults]');
      tb.innerHTML = '';
      if (!out[8].length) {
        tb.innerHTML = '<tr><td colspan="4" class="amd-empty">No check has reported a fault.</td></tr>';
      } else {
        out[8].forEach(function (r) {
          var tr = document.createElement('tr');
          tr.innerHTML =
            '<td><a href="/app/asset-check-sheet/' + q(r.name) + '">' + esc(r.name) + '</a></td>' +
            '<td>' + esc(r.asset || '') + '</td>' +
            '<td>' + (r.check_date ? frappe.datetime.str_to_user(r.check_date) : '') + '</td>' +
            '<td><span class="amd-pill" style="background:rgba(180,83,9,.12);color:#b45309">' +
            esc(r.overall_status || '') + '</span></td>';
          tb.appendChild(tr);
        });
      }

      $('[data-amd-sub]').textContent =
        'As at ' + frappe.datetime.str_to_user(frappe.datetime.get_today()) +
        ' · machines ranked over the last ' + AGO + ' days';
    }).catch(function () {
      $('[data-amd-sub]').textContent = 'Could not load the figures.';
    });
  }

  $('[data-amd-refresh]').addEventListener('click', load);
  load();
})();

style:
.amd{padding:4px 2px;font-family:'Poppins',var(--font-stack),'Inter',sans-serif;}
.amd-hd{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:14px;}
.amd-tt{font-size:15px;font-weight:700;color:var(--heading-color,#1f272e);}
.amd-sub{font-size:12px;color:#8a8f98;margin-top:2px;}
.amd-btn{font-size:12px;font-weight:600;padding:6px 12px;border-radius:8px;border:1px solid var(--border-color,#e2e4e9);background:var(--card-bg,#fff);color:inherit;cursor:pointer;}
.amd-btn:hover{box-shadow:0 2px 6px rgba(0,0,0,.06);}
.amd-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:14px;}
.amd-kpi{border:1px solid var(--border-color,#e2e4e9);border-radius:10px;background:var(--card-bg,#fff);padding:13px 15px;text-decoration:none;color:inherit;display:block;transition:box-shadow .18s ease,transform .18s ease;}
.amd-kpi:hover{box-shadow:0 2px 6px rgba(0,0,0,.06);transform:translateY(-1px);text-decoration:none;color:inherit;}
.amd-kpi-n{font-size:22px;font-weight:700;line-height:1.1;}
.amd-kpi-l{font-size:11.5px;color:#8a8f98;margin-top:3px;line-height:1.3;}
.amd-row{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:12px;margin-bottom:14px;}
.amd-card{border:1px solid var(--border-color,#e2e4e9);border-radius:10px;background:var(--card-bg,#fff);padding:14px 16px;}
.amd-card-t{font-size:13.5px;font-weight:600;}
.amd-card-s{font-size:11px;color:#8a8f98;margin:2px 0 12px;}
.amd-bar-row{display:flex;align-items:center;gap:10px;margin-bottom:8px;}
.amd-bar-lb{font-size:12px;flex:0 0 42%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.amd-bar-lb a{color:inherit;text-decoration:none;}
.amd-bar-lb a:hover{text-decoration:underline;}
.amd-track{flex:1;height:8px;border-radius:4px;background:var(--control-bg,#f0f1f3);overflow:hidden;}
.amd-fill{height:100%;border-radius:4px;}
.amd-bar-vl{font-size:12px;font-weight:600;flex:0 0 34px;text-align:right;}
.amd-scroll{overflow-x:auto;}
.amd-tb{width:100%;border-collapse:collapse;font-size:12.5px;}
.amd-tb th{text-align:left;font-weight:600;color:#8a8f98;font-size:11px;text-transform:uppercase;letter-spacing:.05em;padding:0 10px 7px 0;}
.amd-tb td{padding:7px 10px 7px 0;border-top:1px solid var(--border-color,#eceef1);}
.amd-tb a{color:inherit;text-decoration:none;font-weight:500;}
.amd-tb a:hover{text-decoration:underline;}
.amd-pill{display:inline-block;padding:2px 9px;border-radius:20px;font-size:11px;font-weight:600;}
.amd-empty{font-size:12px;color:#8a8f98;padding:6px 0;}
